[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en" data-theme="dark">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>CommerceForge Dev Docs — Build for the Commerce Platform</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap" rel="stylesheet">
<style>
/* ==========================================
   CommerceForge Design System
   Dark-mode-first, professional developer docs
   ========================================== */

:root {
  /* Backgrounds */
  --bg-primary: oklch(12% 0.02 260);
  --bg-secondary: oklch(16% 0.025 260);
  --bg-tertiary: oklch(20% 0.025 260);
  --bg-elevated: oklch(22% 0.025 260);

  /* Accent */
  --accent: oklch(72% 0.18 160);
  --accent-hover: oklch(78% 0.19 160);
  --accent-muted: oklch(50% 0.10 160);
  --accent-secondary: oklch(65% 0.16 200);

  /* Text */
  --text-primary: oklch(95% 0.01 260);
  --text-secondary: oklch(72% 0.02 260);
  --text-tertiary: oklch(52% 0.02 260);

  /* Borders */
  --border-default: oklch(25% 0.02 260);
  --border-hover: oklch(35% 0.03 260);
  --border-accent: oklch(55% 0.12 160);

  /* Code */
  --code-bg: oklch(9% 0.02 260);
  --code-text: oklch(85% 0.03 160);

  /* Semantic */
  --success: oklch(70% 0.18 145);
  --warning: oklch(75% 0.15 85);

  /* Misc */
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 14px;
  --shadow-sm: 0 1px 3px oklch(0% 0 0 / 0.3);
  --shadow-md: 0 4px 12px oklch(0% 0 0 / 0.4);
  --shadow-lg: 0 8px 30px oklch(0% 0 0 / 0.5);
  --transition-fast: 150ms ease;
  --transition-normal: 250ms ease;
  --transition-slow: 350ms cubic-bezier(0.4, 0, 0.2, 1);

  /* Layout */
  --max-width: 1200px;
  --nav-height: 60px;
}

/* Reset */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  background-color: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  min-height: 100vh;
}

a {
  color: var(--accent);
  text-decoration: none;
  transition: color var(--transition-fast);
}

a:hover {
  color: var(--accent-hover);
}

/* ==========================================
   Navigation
   ========================================== */

.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: oklch(12% 0.02 260 / 0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-default);
  height: var(--nav-height);
}

.nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  padding: 0 24px;
}

.nav-brand {
  display: flex;
  align-items: center;
  gap: 10px;
  font-weight: 700;
  font-size: 1.1rem;
  color: var(--text-primary);
}

.nav-brand-icon {
  width: 32px;
  height: 32px;
  background: linear-gradient(135deg, var(--accent), var(--accent-secondary));
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 0.9rem;
  color: var(--bg-primary);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 4px;
  list-style: none;
}

.nav-links a {
  color: var(--text-secondary);
  padding: 8px 14px;
  border-radius: var(--radius-sm);
  font-size: 0.9rem;
  font-weight: 500;
  transition: color var(--transition-fast), background var(--transition-fast);
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--text-primary);
  background: var(--bg-secondary);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.nav-btn {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-default);
  background: var(--bg-secondary);
  color: var(--text-secondary);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition-fast);
  font-size: 1rem;
}

.nav-btn:hover {
  background: var(--bg-tertiary);
  color: var(--text-primary);
  border-color: var(--border-hover);
}

.nav-login {
  padding: 8px 18px;
  border-radius: var(--radius-sm);
  background: var(--accent);
  color: var(--bg-primary) !important;
  font-weight: 600;
  font-size: 0.85rem;
  transition: background var(--transition-fast);
}

.nav-login:hover {
  background: var(--accent-hover);
}

.nav-mobile-toggle {
  display: none;
  width: 36px;
  height: 36px;
  border: 1px solid var(--border-default);
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
  color: var(--text-secondary);
  cursor: pointer;
  align-items: center;
  justify-content: center;
  font-size: 1.2rem;
}

/* ==========================================
   Hero Section
   ========================================== */

.hero {
  padding: 80px 24px 64px;
  text-align: center;
  max-width: 800px;
  margin: 0 auto;
}

.hero h1 {
  font-size: clamp(2rem, 5vw, 3.2rem);
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: -0.02em;
  margin-bottom: 20px;
  background: linear-gradient(135deg, var(--text-primary) 0%, oklch(85% 0.03 200) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero p {
  color: var(--text-secondary);
  font-size: 1.1rem;
  line-height: 1.7;
  max-width: 640px;
  margin: 0 auto 32px;
}

.hero-ctas {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 12px 24px;
  border-radius: var(--radius-md);
  font-size: 0.95rem;
  font-weight: 600;
  cursor: pointer;
  transition: all var(--transition-fast);
  border: none;
  font-family: inherit;
}

.btn-primary {
  background: var(--accent);
  color: var(--bg-primary);
}

.btn-primary:hover {
  background: var(--accent-hover);
  transform: translateY(-1px);
  box-shadow: 0 4px 20px oklch(72% 0.18 160 / 0.35);
}

.btn-secondary {
  background: var(--bg-secondary);
  color: var(--text-primary);
  border: 1px solid var(--border-default);
}

.btn-secondary:hover {
  background: var(--bg-tertiary);
  border-color: var(--border-hover);
}

.btn-ghost {
  background: transparent;
  color: var(--text-secondary);
  border: 1px solid var(--border-default);
}

.btn-ghost:hover {
  color: var(--text-primary);
  border-color: var(--border-hover);
  background: var(--bg-secondary);
}

/* ==========================================
   Product Cards
   ========================================== */

.section {
  padding: 64px 24px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.section-header {
  text-align: center;
  margin-bottom: 48px;
}

.section-header h2 {
  font-size: 2rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  margin-bottom: 12px;
}

.section-header p {
  color: var(--text-secondary);
  font-size: 1.05rem;
  max-width: 560px;
  margin: 0 auto;
}

.product-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.product-card {
  background: var(--bg-secondary);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: all var(--transition-normal);
  position: relative;
  overflow: hidden;
}

.product-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, var(--accent), var(--accent-secondary));
  opacity: 0;
  transition: opacity var(--transition-normal);
}

.product-card:hover {
  border-color: var(--border-hover);
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.product-card:hover::before {
  opacity: 1;
}

.product-card-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.4rem;
  margin-bottom: 20px;
}

.product-card-icon.apps {
  background: oklch(25% 0.05 160);
  color: var(--accent);
}

.product-card-icon.storefronts {
  background: oklch(25% 0.05 260);
  color: var(--accent-secondary);
}

.product-card-icon.agents {
  background: oklch(25% 0.05 300);
  color: oklch(75% 0.15 300);
}

.product-card h3 {
  font-size: 1.25rem;
  font-weight: 600;
  margin-bottom: 8px;
}

.product-card p {
  color: var(--text-secondary);
  font-size: 0.9rem;
  line-height: 1.6;
  margin-bottom: 20px;
}

.product-card .btn {
  font-size: 0.85rem;
}

/* ==========================================
   CLI Setup Section
   ========================================== */

.cli-setup {
  background: var(--bg-secondary);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-lg);
  padding: 48px;
  max-width: 900px;
  margin: 0 auto;
}

.cli-setup h2 {
  font-size: 1.6rem;
  font-weight: 700;
  margin-bottom: 8px;
}

.cli-setup > p {
  color: var(--text-secondary);
  margin-bottom: 32px;
}

/* Accordion */
.accordion {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.accordion-item {
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: border-color var(--transition-fast);
}

.accordion-item.active {
  border-color: var(--border-accent);
}

.accordion-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 16px 20px;
  background: var(--bg-tertiary);
  border: none;
  color: var(--text-primary);
  font-size: 0.95rem;
  font-weight: 600;
  cursor: pointer;
  font-family: inherit;
  text-align: left;
  transition: background var(--transition-fast);
}

.accordion-header:hover {
  background: var(--bg-elevated);
}

.accordion-header .icon {
  font-size: 1.1rem;
  transition: transform var(--transition-normal);
  color: var(--text-tertiary);
}

.accordion-item.active .accordion-header .icon {
  transform: rotate(180deg);
  color: var(--accent);
}

.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow);
}

.accordion-item.active .accordion-body {
  max-height: 500px;
}

.accordion-content {
  padding: 20px 24px 24px;
}

.accordion-steps {
  list-style: none;
  counter-reset: step;
}

.accordion-steps li {
  counter-increment: step;
  display: flex;
  align-items: flex-start;
  gap: 14px;
  padding: 10px 0;
  color: var(--text-secondary);
  font-size: 0.92rem;
  line-height: 1.6;
}

.accordion-steps li::before {
  content: counter(step);
  flex-shrink: 0;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  background: var(--bg-elevated);
  border: 1px solid var(--border-default);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--text-tertiary);
}

/* Tabs */
.tabs {
  margin-top: 20px;
}

.tabs-nav {
  display: flex;
  gap: 2px;
  border-bottom: 1px solid var(--border-default);
  margin-bottom: 0;
}

.tab-btn {
  padding: 10px 18px;
  border: none;
  background: transparent;
  color: var(--text-tertiary);
  font-size: 0.85rem;
  font-weight: 500;
  cursor: pointer;
  font-family: inherit;
  border-bottom: 2px solid transparent;
  transition: all var(--transition-fast);
  margin-bottom: -1px;
}

.tab-btn:hover {
  color: var(--text-secondary);
}

.tab-btn.active {
  color: var(--accent);
  border-bottom-color: var(--accent);
}

.tab-panel {
  display: none;
}

.tab-panel.active {
  display: block;
}

.code-block {
  background: var(--code-bg);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-sm);
  padding: 16px 20px;
  margin-top: 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.code-block code {
  font-family: 'JetBrains Mono', 'Fira Code', monospace;
  font-size: 0.88rem;
  color: var(--code-text);
}

.copy-btn {
  flex-shrink: 0;
  padding: 6px 12px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-default);
  background: var(--bg-secondary);
  color: var(--text-tertiary);
  cursor: pointer;
  font-size: 0.78rem;
  font-weight: 500;
  font-family: inherit;
  transition: all var(--transition-fast);
}

.copy-btn:hover {
  background: var(--bg-tertiary);
  color: var(--text-primary);
  border-color: var(--border-hover);
}

.copy-btn.copied {
  background: oklch(25% 0.05 145);
  color: var(--success);
  border-color: var(--success);
}

.init-command {
  margin-top: 8px;
  background: var(--code-bg);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-sm);
  padding: 14px 20px;
}

.init-command code {
  font-family: 'JetBrains Mono', 'Fira Code', monospace;
  font-size: 0.88rem;
  color: var(--code-text);
}

.init-command-label {
  display: block;
  font-size: 0.78rem;
  color: var(--text-tertiary);
  font-weight: 500;
  margin-bottom: 6px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

/* ==========================================
   Launch CTA
   ========================================== */

.launch-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}

.launch-card {
  background: var(--bg-secondary);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: all var(--transition-normal);
}

.launch-card:hover {
  border-color: var(--border-hover);
  box-shadow: var(--shadow-md);
}

.launch-card h3 {
  font-size: 1.15rem;
  font-weight: 600;
  margin-bottom: 8px;
}

.launch-card p {
  color: var(--text-secondary);
  font-size: 0.9rem;
  margin-bottom: 16px;
}

/* ==========================================
   Community Section
   ========================================== */

.community-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}

.community-card {
  background: var(--bg-secondary);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
  padding: 24px;
  text-align: center;
  transition: all var(--transition-fast);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
}

.community-card:hover {
  border-color: var(--accent-muted);
  background: var(--bg-tertiary);
}

.community-card-icon {
  font-size: 1.5rem;
}

.community-card span {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--text-primary);
}

/* ==========================================
   Footer
   ========================================== */

.footer {
  border-top: 1px solid var(--border-default);
  background: var(--bg-secondary);
  padding: 64px 24px 40px;
  margin-top: 64px;
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 40px;
  margin-bottom: 48px;
}

.footer-col h4 {
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-tertiary);
  margin-bottom: 16px;
}

.footer-col ul {
  list-style: none;
}

.footer-col li {
  margin-bottom: 8px;
}

.footer-col a {
  color: var(--text-secondary);
  font-size: 0.88rem;
}

.footer-col a:hover {
  color: var(--text-primary);
}

.footer-bottom {
  border-top: 1px solid var(--border-default);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.82rem;
  color: var(--text-tertiary);
}

/* ==========================================
   Utility: Divider
   ========================================== */

.divider {
  border: none;
  border-top: 1px solid var(--border-default);
  margin: 0;
}

/* ==========================================
   Responsive
   ========================================== */

@media (max-width: 1024px) {
  .product-grid {
    grid-template-columns: 1fr;
    max-width: 500px;
    margin: 0 auto;
  }

  .community-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .launch-grid {
    grid-template-columns: 1fr;
    max-width: 500px;
    margin: 0 auto;
  }

  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .nav-links {
    display: none;
    position: absolute;
    top: var(--nav-height);
    left: 0;
    right: 0;
    background: var(--bg-primary);
    border-bottom: 1px solid var(--border-default);
    flex-direction: column;
    padding: 12px 16px;
    gap: 2px;
  }

  .nav-links.open {
    display: flex;
  }

  .nav-links a {
    padding: 10px 14px;
    width: 100%;
  }

  .nav-mobile-toggle {
    display: flex;
  }

  .hero {
    padding: 48px 20px 40px;
  }

  .hero h1 {
    font-size: 1.8rem;
  }

  .section {
    padding: 40px 20px;
  }

  .cli-setup {
    padding: 28px 20px;
  }

  .community-grid {
    grid-template-columns: 1fr;
  }

  .footer-bottom {
    flex-direction: column;
    gap: 8px;
    text-align: center;
  }

  .nav-actions .nav-login {
    font-size: 0.8rem;
    padding: 6px 14px;
  }
}

@media (max-width: 480px) {
  .hero-ctas {
    flex-direction: column;
    align-items: center;
  }

  .hero-ctas .btn {
    width: 100%;
    justify-content: center;
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }

  .nav-brand {
    font-size: 0.95rem;
  }
}
</style>
</head>
<body>

<!-- Navigation -->
<nav class="nav" role="navigation">
  <div class="nav-inner">
    <a href="index.html" class="nav-brand">
      <div class="nav-brand-icon">CF</div>
      CommerceForge
    </a>
    <ul class="nav-links" id="navLinks">
      <li><a href="apps-build.html">Apps</a></li>
      <li><a href="storefronts.html">Storefronts</a></li>
      <li><a href="agents.html">Agents</a></li>
      <li><a href="#">References</a></li>
      <li><a href="support.html">Help</a></li>
    </ul>
    <div class="nav-actions">
      <button class="nav-btn" id="themeToggle" aria-label="Toggle theme" title="Toggle theme">☀</button>
      <button class="nav-btn" id="searchBtn" aria-label="Search" title="Search">⌘</button>
      <a href="#" class="nav-login">Log in</a>
      <button class="nav-mobile-toggle" id="mobileToggle" aria-label="Menu">☰</button>
    </div>
  </div>
</nav>

<!-- Hero -->
<section class="hero">
  <h1>CommerceForge Dev Docs</h1>
  <p>Learn how to build an app, or customize your storefront. Whether you're just getting started, deep in the development process, or ready to distribute and monetize your work, CommerceForge's docs, dev tools and frameworks make building easy and efficient.</p>
  <div class="hero-ctas">
    <a href="apps-build.html" class="btn btn-primary">Build your first app →</a>
    <a href="storefronts.html" class="btn btn-secondary">Build a storefront →</a>
    <a href="agents.html" class="btn btn-ghost">Build agents with UCP →</a>
  </div>
</section>

<!-- Product Cards -->
<section class="section">
  <div class="section-header">
    <h2>Build anything on CommerceForge</h2>
    <p>Three powerful ways to extend the commerce platform, each with dedicated tooling and documentation.</p>
  </div>
  <div class="product-grid">
    <div class="product-card" id="cardApps">
      <div class="product-card-icon apps">⬡</div>
      <h3>Apps</h3>
      <p>Extend CommerceForge's core functionality with apps that integrate into the admin, online store, checkout and more.</p>
      <a href="apps-build.html" class="btn btn-ghost">Build your first app →</a>
    </div>
    <div class="product-card" id="cardStorefronts">
      <div class="product-card-icon storefronts">◈</div>
      <h3>Storefronts</h3>
      <p>Help merchants express their unique brand by building a custom theme or Hydrogen storefront.</p>
      <a href="storefronts.html" class="btn btn-ghost">Build a storefront →</a>
    </div>
    <div class="product-card" id="cardAgents">
      <div class="product-card-icon agents">◉</div>
